# Build a description from the module path and its top-level definitions.
def describe(p):
    parts = p[:-3].split('/')
    # drop leading 'django'
    parts = parts[1:]
    modname = '.'.join(parts)
    src = open(p, encoding='utf-8').read()
    tree = ast.parse(src)
    classes = [n.name for n in tree.body if isinstance(n, ast.ClassDef) and not n.name.startswith('_')]
    funcs = [n.name for n in tree.body if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef)) and not n.name.startswith('_')]
    assigns = []
