# Build a description for each file based on its path and top-level definitions.
def describe(p):
    parts = p[:-3].split('/')
    name = parts[-1]
    parent = parts[-2]
    src = open(p, encoding='utf-8').read()
    try:
        tree = ast.parse(src)
    except SyntaxError:
        tree = None
    classes = []
    funcs = []
    if tree:
        for node in tree.body:
            if isinstance(node, ast.ClassDef):
                classes.append(node.name)
            elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                funcs.append(node.name)
    if name == '__init__':
        if classes or funcs:
            names = ', '.join((classes + funcs)[:4])
            return f'Package initializer for {parent}, exposing {names}.'
        return f'Package initializer for the {parent} package.'
    if classes and funcs:
        return f'Provides {name.replace("_", " ")} functionality, including {classes[0]} and {funcs[0]}().'
    if classes:
        return f'Defines {name.replace("_", " ")} classes such as {classes[0]}.'
    if funcs:
        return f'Provides {name.replace("_", " ")} helper functions such as {funcs[0]}().'
    return f'Module {name} in the {parent} package.'

changed = 0
for p in missing:
    src = open(p, encoding='utf-8').read()
    lines = src.splitlines(keepends=True)
    insert_at = 0
    for i, line in enumerate(lines):
        s = line.strip()
        if s.startswith('#!') or (i == 0 and s.startswith('# -*- coding')) or (i == 1 and s.startswith('# -*- coding')):
            insert_at = i + 1
            continue
        break
    doc = describe(p)
    new_lines = lines[:insert_at] + ['"""' + doc + '"""\n'] + lines[insert_at:]
    open(p, 'w', encoding='utf-8').write(''.join(new_lines))
    changed += 1
print('changed', changed)
